draw_group:
function (data, panel_params, coord, lineend = "butt", na.rm = FALSE, 
    binaxis = "x", stackdir = "up", stackratio = 1, dotsize = 1, 
    stackgroups = FALSE) 
{
    if (!coord$is_linear()) {
        cli::cli_warn("{.fn geom_dotplot} does not work properly with non-linear coordinates.")
    }
    tdata <- coord$transform(data, panel_params)
    if (inherits(coord, "CoordFlip")) 
        binaxis <- ifelse(binaxis == "x", "y", "x")
    if (binaxis == "x") {
        stackaxis <- "y"
        dotdianpc <- dotsize * tdata$binwidth[1]/(max(panel_params$x.range) - 
            min(panel_params$x.range))
    }
    else if (binaxis == "y") {
        stackaxis <- "x"
        dotdianpc <- dotsize * tdata$binwidth[1]/(max(panel_params$y.range) - 
            min(panel_params$y.range))
    }
    ggname("geom_dotplot", dotstackGrob(stackaxis = stackaxis, 
        x = tdata$x, y = tdata$y, dotdia = dotdianpc, stackposition = tdata$stackpos, 
        stackdir = stackdir, stackratio = stackratio, default.units = "npc", 
        gp = gg_par(col = alpha(tdata$colour, tdata$alpha), fill = fill_alpha(tdata$fill, 
            tdata$alpha), lwd = tdata$stroke/.pt, lty = tdata$linetype, 
            lineend = lineend)))
}
